
#[cfg(test)]
mod freeze50_scene_development_tests {
    use super::*;
    #[test]
    #[ignore="LITO_SHARED_RESOURCE_ROOT; original756/219, silent bank, history/retirement and memory fragments only"]
    fn original_silent_class4_history_ring_eviction_arrival_and_failed_reprepare() {
        let root:std::path::PathBuf=std::env::var_os("LITO_SHARED_RESOURCE_ROOT").expect("explicit shared root").into();let cancel=AtomicBool::new(false);let mut w=super::super::native_login::LoginController::default().snapshot().world.clone();let f:serde_json::Value=serde_json::from_slice(include_bytes!(r"D:\lineage開發\3-lito開發\lito重建版\LiTo381-Modern\tests\fixtures\native-world-current.json")).unwrap();for key in ["world","start","status","actor","bot"]{let h=f["packets"][key].as_str().unwrap();let b:Vec<_>=(0..h.len()).step_by(2).map(|i|u8::from_str_radix(&h[i..i+2],16).unwrap()).collect();w.accept(&b).unwrap();}
        w.learned_skills.clear();w.learned_skills.insert(50);let own=w.own_actor().unwrap().clone();let id=0x71234567;let mut a=own.clone();a.id=id;a.x+=6;a.incarnation+=1;w.actors.insert(id,a.clone());let cue=ProjectileCue{heading:2,attacker_incarnation:own.incarnation,target_incarnation:Some(a.incarnation),action_sequence:999,attacker:own.id,target:id,damage_marker:10,projectile:super::super::native_combat::Projectile{id:77,graphics:756,flight_type:0,from:[own.x,own.y],to:[a.x,a.y]}};w.projectiles.push(cue.clone());let event=EnteredEvent{actor:own.id,sequence:999,action:18,frame:1,event:"Hit".into(),sound:None,prepared_audio:None};let view=ViewProjection{anchor_cell:WorldCell{x:i32::from(own.x),y:i32::from(own.y)},anchor_pixel:super::super::world_map::PixelPoint{x:400,y:300}};
        let mut p=Projectiles::default();p.prepare(&root,&w,&cancel);assert!(p.errors.is_empty());let bank=&p.assets[&756];assert!(bank.sound_group().is_none());assert!(bank.sound_bank().is_empty());assert_eq!(bank.sprite_sources().filter(|s|s.name.starts_with("756-")).count(),4);assert!(p.update(&w,[&event].into_iter(),0).is_empty());let mut fragments=vec![];let(receipt,audio)=p.draw_to(&mut super::super::native_world_effects::Target::Fragments(&mut fragments),view,0);assert_eq!(receipt["launched"],1);assert!(audio.is_empty());assert_eq!(fragments.len(),1);drop(fragments);let h=p.history();
        let mut restored=Projectiles::default();restored.restore_history(h.clone(),true);w.projectiles.clear();w.learned_skills.clear();restored.prepare(&root,&w,&cancel);assert!(restored.assets.contains_key(&756));assert!(restored.update(&w,std::iter::empty(),60_000_000).is_empty());assert!(restored.seen.contains(&(own.id,999)));w.projectiles.push(cue);assert!(restored.update(&w,[&event].into_iter(),60_000_000).is_empty());assert_eq!(restored.launched,1);
        w.actors.get_mut(&id).unwrap().x+=1;let before=serde_json::to_value(&w).unwrap();for now in [120,180,240,300] {assert!(restored.update(&w,std::iter::empty(),now*1_000_000).is_empty());let mut fragments=vec![];let(_,audio)=restored.draw_to(&mut super::super::native_world_effects::Target::Fragments(&mut fragments),view,now*1_000_000);assert!(audio.is_empty());}assert_eq!(restored.arrived,1);assert_eq!(restored.flights[0].path.target().x,i32::from(a.x));assert_eq!(serde_json::to_value(&w).unwrap(),before);
        let mut retired=Projectiles::default();retired.restore_history(h.clone(),false);retired.prepare(&root,&w,&cancel);retired.update(&w,[&event].into_iter(),0);assert!(retired.flights.is_empty());assert_eq!(retired.launched,1);
        let mut failed=Projectiles::default();failed.restore_history(h,true);let cancelled=AtomicBool::new(true);failed.prepare(&root,&w,&cancelled);assert!(failed.errors.contains_key(&756));failed.update(&w,std::iter::empty(),60_000_000);assert_eq!(failed.omitted,1);assert!(failed.flights.iter().all(|f|f.finished));failed.update(&w,std::iter::empty(),120_000_000);assert_eq!(failed.omitted,1);w.generation+=1;restored.update(&w,std::iter::empty(),400_000_000);assert!(restored.flights.is_empty());
    }
}
